class Library {
  private ArrayList<Book> books = new ArrayList<>();
  void addBook(Book b) { books.add(b); }
  void printAll() { for (Book b : books) System.out.println(b); }
  Book cheapest() {
    Book c = books.get(0);
    for (Book b : books) if (b.getPrice() < c.getPrice()) c = b;
    return c;
  }
}
